SET ROLE talus_fn;
CREATE OR REPLACE FUNCTION app.create_price_snapshot(p_id uuid,p_booking uuid,p_rate uuid,pickup timestamptz,dropoff timestamptz,tz text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,public AS $$ DECLARE t uuid:=app.current_context_tenant_id();q jsonb;v_step text:='start';BEGIN v_step:='authorizing';PERFORM app.require_staff_role('staff');v_step:='calculating quote';q:=app.calculate_quote(p_rate,pickup,dropoff,tz);v_step:='inserting pricing_revision (current_user: '||current_user||', session_user: '||session_user||')';INSERT INTO app.pricing_revision VALUES(t,p_id,p_booking,1,'confirmed',NULL,clock_timestamp());v_step:='inserting price_line';INSERT INTO app.price_line VALUES(t,p_id,1,'rental_subtotal',(q->>'rental_subtotal_cents')::bigint,NULL),(t,p_id,2,'total',(q->>'total_cents')::bigint,NULL);v_step:='appending audit';PERFORM app.append_audit('pricing.snapshot_created','pricing_revision',p_id);RETURN p_id;EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'M04 TRACE FAILED at step [%]: % (SQLSTATE %)',v_step,SQLERRM,SQLSTATE USING ERRCODE='P0001';END; $$;
RESET ROLE;
